#![cfg(feature="test-hook")]
#[path="../src/semantic.rs"] mod semantic;
use semantic::SemanticService;
use rusqlite::Connection;
use std::{sync::mpsc,thread,time::{Duration,Instant},path::Path,process::Command};
const SERVER:&str=concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/mock-embedding-server.py");
fn wait_for(mut f:impl FnMut()->bool){let end=Instant::now()+Duration::from_secs(30);while Instant::now()<end {if f(){return}thread::sleep(Duration::from_millis(25))}panic!("timed out")}
fn start(p:&Path)->SemanticService {SemanticService::start(SERVER,p.join("fake.gguf").to_str().unwrap()).unwrap()}
#[test] #[ignore] fn child(){let p=std::path::PathBuf::from(std::env::var("ATLAS_RACE_PATH").unwrap());let (tx,rx)=mpsc::channel();let (resume_tx,resume_rx)=mpsc::channel();let s=SemanticService::start_with_hook(SERVER,p.join("fake.gguf").to_str().unwrap(),tx,resume_rx).unwrap();s.enqueue(&p,None).unwrap();rx.recv_timeout(Duration::from_secs(30)).unwrap();std::fs::write(p.join("ready"),b"ready").unwrap();wait_for(||p.join("resume").exists());resume_tx.send(()).unwrap();wait_for(||s.status(&p)["available"]==true);s.close(&p).unwrap();}
#[test] fn prepare_serializes_processes(){let p=std::env::temp_dir().join(format!("atlas-prepare-race-{}",std::process::id()));atlas_native_storage_contract::create_workspace(&p).unwrap();std::fs::write(p.join("fake.gguf"),b"test").unwrap();std::env::set_var("ATLAS_TEST_FAKE_ENCODER_LOG",p.join("calls"));let db=Connection::open(p.join("atlas.sqlite3")).unwrap();db.execute_batch("INSERT INTO objects(id,kind,title,path,description,text_status) VALUES ('a','note','test','','','available');INSERT INTO search_index(object_id,title,body) VALUES ('a','test','old body');").unwrap();let s=start(&p);s.enqueue(&p,None).unwrap();wait_for(||s.status(&p)["available"]==true);let d=p.join(".atlas-semantic-native");let initial=std::fs::read_to_string(d.join("current")).unwrap();let mut child=Command::new(std::env::current_exe().unwrap()).args(["--exact","child","--ignored","--nocapture"]).env("ATLAS_RACE_PATH",&p).spawn().unwrap();wait_for(||p.join("ready").exists());{let _guard=atlas_native_storage_contract::workspace_lock(&p).unwrap();db.execute("UPDATE search_index SET body='new body' WHERE object_id='a'",[]).unwrap();}s.enqueue(&p,Some("a")).unwrap();thread::sleep(Duration::from_millis(800));let before=std::fs::read_to_string(d.join("current")).unwrap();let initial_exists=d.join(initial.trim()).exists();std::fs::write(p.join("resume"),b"go").unwrap();assert!(child.wait().unwrap().success());wait_for(||s.status(&p)["available"]==true && std::fs::read_to_string(d.join("current")).unwrap()!=initial);let current=std::fs::read_to_string(d.join("current")).unwrap();assert!(d.join(current.trim()).exists());assert_eq!(before,initial,"another writer published before the first completed");assert!(initial_exists,"another writer cleaned up a generation still in use");let result=s.search(&p,"new body",Some(&["a".into()])).unwrap();assert!(result[0]["chunks"][0]["text"].as_str().unwrap().contains("new body"));s.close(&p).unwrap();drop(db);std::fs::remove_dir_all(p).unwrap();}
